PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default 'sale_manager');
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "snooker_tables" ("id" integer primary key autoincrement not null, "number" integer not null, "name" varchar not null, "hourly_rate" numeric not null default '600', "is_active" tinyint(1) not null default '1', "notes" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "players" ("id" integer primary key autoincrement not null, "name" varchar not null, "phone" varchar, "email" varchar, "is_active" tinyint(1) not null default '1', "notes" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "staff" ("id" integer primary key autoincrement not null, "name" varchar not null, "phone" varchar, "role" varchar not null default 'manager', "commission_rate" numeric not null default '25', "is_active" tinyint(1) not null default '1', "notes" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "add_on_items" ("id" integer primary key autoincrement not null, "name" varchar not null, "unit_price" numeric not null, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "cash_deposits" ("id" integer primary key autoincrement not null, "deposit_date" date not null, "staff_id" integer, "opening_petty_cash" numeric not null default '0', "amount_collected_from_staff" numeric not null default '0', "petty_cash_kept" numeric not null default '0', "bank_deposit_amount" numeric not null default '0', "notes" text, "created_at" datetime, "updated_at" datetime, "closing_source" varchar not null default 'system', "manual_table_1_sale" numeric not null default '0', "manual_table_2_sale" numeric not null default '0', "manual_table_3_sale" numeric not null default '0', "manual_table_4_sale" numeric not null default '0', "manual_expense_total" numeric not null default '0', "staff_paid_amount" numeric not null default '0', "cash_collected_from_counter" numeric not null default '0', "dues_added" numeric not null default '0', "dues_recovered" numeric not null default '0', "customer_dues" text, "staff_paid_to_all" tinyint(1) not null default '0', foreign key("staff_id") references "staff"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "monthly_commissions" ("id" integer primary key autoincrement not null, "staff_id" integer not null, "month" date not null, "cash_collected" numeric not null default '0', "expense_total" numeric not null default '0', "net_profit" numeric not null default '0', "commission_rate" numeric not null default '25', "commission_amount" numeric not null default '0', "carried_forward_from_previous" numeric not null default '0', "advances_deducted" numeric not null default '0', "paid_amount" numeric not null default '0', "balance_due" numeric not null default '0', "generated_at" datetime, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("staff_id") references "staff"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "game_sessions" ("id" integer primary key autoincrement not null, "snooker_table_id" integer not null, "game_type" varchar not null default 'one_to_one', "status" varchar not null default 'active', "started_at" datetime not null, "ended_at" datetime, "checked_out_at" datetime, "frames_played" integer not null default '1', "frame_fee" numeric not null default '100', "hourly_rate" numeric not null default '600', "discount_total" numeric not null default '0', "created_by" integer, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("snooker_table_id") references "snooker_tables"("id") on delete restrict, foreign key("created_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "game_participants" ("id" integer primary key autoincrement not null, "game_session_id" integer not null, "player_id" integer, "player_name_snapshot" varchar, "team" varchar not null default 'solo', "is_loser" tinyint(1) not null default '0', "base_amount" numeric not null default '0', "discount_amount" numeric not null default '0', "add_on_amount" numeric not null default '0', "total_due" numeric not null default '0', "amount_paid" numeric not null default '0', "payment_status" varchar not null default 'unpaid', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("game_session_id") references "game_sessions"("id") on delete cascade, foreign key("player_id") references "players"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "game_add_ons" ("id" integer primary key autoincrement not null, "game_session_id" integer not null, "add_on_item_id" integer, "item_name" varchar not null, "unit_price" numeric not null, "quantity" numeric not null default '1', "total_amount" numeric not null default '0', "charged_to" varchar not null default 'losers', "player_id" integer, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("game_session_id") references "game_sessions"("id") on delete cascade, foreign key("add_on_item_id") references "add_on_items"("id") on delete set null, foreign key("player_id") references "players"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "payments" ("id" integer primary key autoincrement not null, "game_session_id" integer, "game_participant_id" integer, "player_id" integer, "collected_by_staff_id" integer, "payment_date" date not null, "payment_method" varchar not null default 'cash', "amount" numeric not null, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("game_session_id") references "game_sessions"("id") on delete cascade, foreign key("game_participant_id") references "game_participants"("id") on delete cascade, foreign key("player_id") references "players"("id") on delete set null, foreign key("collected_by_staff_id") references "staff"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "staff_transactions" ("id" integer primary key autoincrement not null, "staff_id" integer not null, "transaction_date" date not null, "commission_month" date, "type" varchar not null default ('advance'), "amount" numeric not null, "description" varchar, "created_at" datetime, "updated_at" datetime, "cash_deposit_id" integer, "paid_from" varchar not null default 'cash', foreign key("staff_id") references staff("id") on delete cascade on update no action, foreign key("cash_deposit_id") references "cash_deposits"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "owner_capitals" ("id" integer primary key autoincrement not null, "entry_date" date not null, "type" varchar not null default 'investment', "amount" numeric not null, "description" varchar, "notes" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "capital_liabilities" ("id" integer primary key autoincrement not null, "start_date" date not null, "title" varchar not null, "source_type" varchar not null default 'friend', "lender_name" varchar, "category" varchar not null default 'Other', "principal_amount" numeric not null, "installment_amount" numeric not null default '0', "installment_frequency" varchar not null default 'monthly', "due_date" date, "status" varchar not null default 'active', "notes" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "capital_liability_payments" ("id" integer primary key autoincrement not null, "capital_liability_id" integer not null, "payment_date" date not null, "amount" numeric not null, "paid_from" varchar not null default 'cash', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("capital_liability_id") references "capital_liabilities"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "expenses" ("id" integer primary key autoincrement not null, "expense_date" date not null, "staff_id" integer, "category" varchar not null default ('General'), "description" varchar not null, "amount" numeric not null, "paid_from" varchar not null default ('cash'), "notes" text, "created_at" datetime, "updated_at" datetime, "cash_deposit_id" integer, foreign key("staff_id") references staff("id") on delete set null on update no action, foreign key("cash_deposit_id") references "cash_deposits"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "customer_dues" ("id" integer primary key autoincrement not null, "customer_name" varchar not null, "phone" varchar, "opening_balance" numeric not null default '0', "total_charged" numeric not null default '0', "total_paid" numeric not null default '0', "balance_due" numeric not null default '0', "notes" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "customer_due_charges" ("id" integer primary key autoincrement not null, "customer_due_id" integer not null, "cash_deposit_id" integer, "charge_date" date not null, "amount" numeric not null, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("customer_due_id") references "customer_dues"("id") on delete cascade, foreign key("cash_deposit_id") references "cash_deposits"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "customer_due_payments" ("id" integer primary key autoincrement not null, "customer_due_id" integer not null, "cash_deposit_id" integer, "payment_date" date not null, "amount" numeric not null, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("customer_due_id") references "customer_dues"("id") on delete cascade, foreign key("cash_deposit_id") references "cash_deposits"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "commission_rates" ("id" integer primary key autoincrement not null, "rate" numeric not null default '25', "effective_from" date not null, "is_active" tinyint(1) not null default '1', "notes" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "bank_transactions" ("id" integer primary key autoincrement not null, "transaction_date" date not null, "type" varchar not null, "amount" numeric not null, "source_type" varchar, "source_id" integer, "description" varchar, "notes" text, "created_at" datetime, "updated_at" datetime);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "snooker_tables_number_unique" on "snooker_tables" ("number");
CREATE UNIQUE INDEX "players_phone_unique" on "players" ("phone");
CREATE UNIQUE INDEX "add_on_items_name_unique" on "add_on_items" ("name");
CREATE INDEX "cash_deposits_deposit_date_index" on "cash_deposits" ("deposit_date");
CREATE UNIQUE INDEX "monthly_commissions_staff_id_month_unique" on "monthly_commissions" ("staff_id", "month");
CREATE INDEX "monthly_commissions_month_index" on "monthly_commissions" ("month");
CREATE INDEX "game_sessions_game_type_index" on "game_sessions" ("game_type");
CREATE INDEX "game_sessions_status_index" on "game_sessions" ("status");
CREATE INDEX "game_sessions_started_at_index" on "game_sessions" ("started_at");
CREATE INDEX "game_sessions_ended_at_index" on "game_sessions" ("ended_at");
CREATE INDEX "game_sessions_checked_out_at_index" on "game_sessions" ("checked_out_at");
CREATE INDEX "game_participants_team_index" on "game_participants" ("team");
CREATE INDEX "game_participants_is_loser_index" on "game_participants" ("is_loser");
CREATE INDEX "game_participants_payment_status_index" on "game_participants" ("payment_status");
CREATE INDEX "payments_payment_date_index" on "payments" ("payment_date");
CREATE INDEX "staff_transactions_commission_month_index" on "staff_transactions" ("commission_month");
CREATE INDEX "staff_transactions_transaction_date_index" on "staff_transactions" ("transaction_date");
CREATE INDEX "owner_capitals_entry_date_index" on "owner_capitals" ("entry_date");
CREATE INDEX "capital_liabilities_start_date_index" on "capital_liabilities" ("start_date");
CREATE INDEX "capital_liability_payments_payment_date_index" on "capital_liability_payments" ("payment_date");
CREATE INDEX "expenses_expense_date_index" on "expenses" ("expense_date");
CREATE UNIQUE INDEX "customer_dues_customer_name_unique" on "customer_dues" ("customer_name");
CREATE INDEX "customer_due_charges_charge_date_index" on "customer_due_charges" ("charge_date");
CREATE INDEX "customer_due_payments_payment_date_index" on "customer_due_payments" ("payment_date");
CREATE INDEX "commission_rates_effective_from_index" on "commission_rates" ("effective_from");
CREATE UNIQUE INDEX "bank_transactions_source_type_source_id_unique" on "bank_transactions" ("source_type", "source_id");
CREATE INDEX "bank_transactions_source_type_source_id_index" on "bank_transactions" ("source_type", "source_id");
CREATE INDEX "bank_transactions_transaction_date_index" on "bank_transactions" ("transaction_date");
CREATE INDEX "bank_transactions_type_index" on "bank_transactions" ("type");
COMMIT;
